3	// Lab6 (Tomasulo OoO core) verification testbench — program 1 (core/rom.mem, test.s).
4	//
5	// In this core the "WB stage" is the CDB broadcast that commits results into
6	// the register file inside Regs (instance name `register` in RV32core):
7	//   - core.cdb_rs_num  : nonzero tag => a result is being broadcast this cycle
8	//   - core.cdb_data    : write-back data   (also on output port wb_data)
9	//   - core.cdb_pc      : PC of the instruction (also on output port wb_addr)
10	//   - destination rd   : the register i whose core.register.rat[i] == cdb_rs_num;
11	//                        core.register.register[i] <= cdb_data at the negedge.
12	//
13	// Hand-executed expectations for test.s with ram.mem data:
14	//   x2=8 (lw 4)  x4=16 (lw 8)  x1=24 (add)  x1=23 (addi -1)
15	//   x5=20 (lw 12)  x6=0xFFFF0000 (lw 16)  x7=0x0FFF0000 (lw 20)
16	//   x1=8 (sub)  x1=0xFFFFFFFD (addi x10,-3)
17	//   beq x4,x5 not taken; beq x4,x4 taken -> 0x40
18	//   x1=0x4000 (lui 4)  x1=0x48 (jal +12 -> 0x50)
19	//   x1=0xFFFF0050 (auipc 0xffff0 @0x50)
20	//   x8=0x01FFE000 (div x7/8)  x9=0x140 (mul 16*20)  x9=0x0FFF0000 (mul x8*8)
21	//   x2=4 (addi)  x1=0x68 (jalr 0(x0) -> PC=0, program restarts)
22	
23	module lab6_tb;
24	
25	    reg clk, rst;
26	    wire [31:0] wb_addr, wb_data;
27	
28	    RV32core core(
29	        .debug_en(1'b0),
30	        .debug_step(1'b0),
31	        .debug_addr(7'b0),
32	        .debug_data(),
33	        .wb_addr(wb_addr),
34	        .wb_data(wb_data),
35	        .clk(clk),
36	        .rst(rst),
37	        .interrupter(1'b0)
38	    );
39	
40	    initial begin
41	        clk = 0;
42	        rst = 1;
43	        #10 rst = 0;
44	    end
45	    always #1 clk = ~clk;
46	
47	    integer cycle = 0;
48	    integer wb_count = 0;
49	    integer x_errors = 0;
50	    integer errors = 0;
51	    integer logf;
52	    integer i, rd;
53	    integer jalr_seen = 0;
54	    integer checked = 0;
55	    reg seen_div, seen_mul1, seen_mul2, seen_jalr;
56	
57	    initial logf = $fopen("wb_log_prog1.txt", "w");
58	    initial begin
59	        seen_div = 0; seen_mul1 = 0; seen_mul2 = 0; seen_jalr = 0;
60	    end
61	
62	    // WB (CDB commit) monitor
63	    always @(posedge clk) begin
64	        if (!rst) begin
65	            cycle = cycle + 1;
66	            if (core.cdb_rs_num !== 8'b0) begin
67	                if (^core.cdb_rs_num === 1'bx || ^core.cdb_data === 1'bx ||
68	                    ^core.cdb_pc === 1'bx) begin
69	                    x_errors = x_errors + 1;
70	                    $display("X/Z on CDB at cycle %0d: rs=%b data=%h pc=%h",
71	                             cycle, core.cdb_rs_num, core.cdb_data, core.cdb_pc);
72	                end
73	                // resolve destination register through the RAT
74	                rd = -1;
75	                for (i = 1; i < 32; i = i + 1)
76	                    if (core.register.rat[i] == core.cdb_rs_num) rd = i;
77	                wb_count = wb_count + 1;
78	                if (rd > 0)
79	                    $fdisplay(logf, "cycle=%0d pc=%h rd=x%0d data=%h",
80	                              cycle, core.cdb_pc, rd, core.cdb_data);
81	                else
82	                    $fdisplay(logf, "cycle=%0d pc=%h rd=- (no reg waits; branch/tag free) data=%h",
83	                              cycle, core.cdb_pc, core.cdb_data);
84	                // first pass ends when the jalr @0x64 commits
85	                if (core.cdb_pc === 32'h64) jalr_seen = jalr_seen + 1;
86	                // in-flight-at-snapshot results are checked at their commit events
87	                if (core.cdb_pc === 32'h54 &&
88	                    (rd !== 8 || core.cdb_data !== 32'h01FFE000)) begin
89	                    $display("FAIL: div commit pc=54 rd=x%0d data=%h, expected x8=01ffe000",
90	                             rd, core.cdb_data);
91	                    errors = errors + 1;
92	                end
93	                if (core.cdb_pc === 32'h58 && core.cdb_data !== 32'h00000140) begin
94	                    // note: rd not checked here — this x9 write is superseded by the
95	                    // mul @0x5c (WAW), so no RAT entry matches its tag at broadcast.
96	                    $display("FAIL: mul1 commit pc=58 data=%h, expected 00000140",
97	                             core.cdb_data);
98	                    errors = errors + 1;
99	                end
100	                if (core.cdb_pc === 32'h5c &&
101	                    (rd !== 9 || core.cdb_data !== 32'h0FFF0000)) begin
102	                    $display("FAIL: mul2 commit pc=5c rd=x%0d data=%h, expected x9=0fff0000",
103	                             rd, core.cdb_data);
104	                    errors = errors + 1;
105	                end
106	            end
107	            // check outputs match internal CDB signals
108	            if (wb_addr !== core.cdb_pc || wb_data !== core.cdb_data) begin
109	                $display("MISMATCH wb_addr/wb_data vs cdb at cycle %0d", cycle);
110	                errors = errors + 1;
111	            end
112	
113	            if (jalr_seen == 1 && !checked) begin
114	                checked = 1;
115	                @(negedge clk); // let the commit land in the register file
116	                check_regs;
117	            end
118	
119	            if (cycle > 4000) begin
120	                $display("--- end of sim: %0d WB broadcasts, %0d X/Z errors, %0d errors ---",
121	                         wb_count, x_errors, errors);
122	                if (jalr_seen < 2)
123	                    $display("FAIL: jalr @0x64 committed only %0d times (program should loop back to PC=0 and run again)", jalr_seen);
124	                else
125	                    $display("PASS: program looped back and re-ran (jalr committed %0d times)", jalr_seen);
126	                $finish;
127	            end
128	        end
129	    end
130	
131	    task exp_reg;
132	        input [4:0] r;
133	        input [31:0] v;
134	        begin
135	            if (core.register.register[r] !== v) begin
136	                $display("FAIL: x%0d = %h, expected %h", r, core.register.register[r], v);
137	                errors = errors + 1;
138	            end
139	        end
140	    endtask
141	
142	    task check_regs;
143	        begin
144	            $display("--- register check at first jalr commit (cycle %0d) ---", cycle);
145	            $display("(x8/x9 still in flight; verified at their commit events)");
146	            exp_reg(1,  32'h00000068); // jalr return address 0x64+4
147	            exp_reg(2,  32'd4);
148	            exp_reg(4,  32'd16);
149	            exp_reg(5,  32'd20);
150	            exp_reg(6,  32'hFFFF0000);
151	            exp_reg(7,  32'h0FFF0000);
152	            for (i = 10; i < 32; i = i + 1) exp_reg(i[4:0], 32'b0);
153	            exp_reg(3, 32'b0);
154	            if (errors == 0 && x_errors == 0)
155	                $display("PASS: all register values match hand-executed expectations");
156	        end
157	    endtask
158	
159	endmodule

