62	            if (uart_len < 8192) begin
63	                uart_bytes[uart_len] = core.mem.ram.uart_char;
64	                uart_len = uart_len + 1;
65	            end
66	        end
67	    end
68	
69	    always @(posedge clk) begin
70	        if (!rst) begin
71	            cycle = cycle + 1;
72	
73	            if (core.cdb_rs_num !== 8'b0) begin
74	                if (^core.cdb_rs_num === 1'bx || ^core.cdb_data === 1'bx ||
75	                    ^core.cdb_pc === 1'bx) begin
76	                    x_errors = x_errors + 1;
77	                    $display("X/Z on CDB at cycle %0d", cycle);
78	                end
79	                wb_count = wb_count + 1;
80	                // park loop: jal zero,0x21c (self) after main returns
81	                if (core.cdb_pc === 32'h21c) park_count = park_count + 1;
82	                // halt at 0x204 means a check() in the sort program failed
83	                if (core.cdb_pc === 32'h204) halt_seen = halt_seen + 1;
84	            end
85	
86	            if (park_count > 40) begin
87	                $display("--- park loop reached at cycle %0d, %0d WB broadcasts ---",
88	                         cycle, wb_count);
89	                check_results;
90	                $finish;
91	            end
92	            if (cycle > 3000000) begin
93	                $display("--- TIMEOUT at cycle %0d (park_count=%0d) ---", cycle, park_count);
94	                errors = errors + 1;
95	                check_results;
96	                $finish;
97	            end
98	        end
99	    end
100	
101	    task check_results;
102	        begin
103	            if (halt_seen > 0) begin
104	                $display("FAIL: halt (0x204) reached %0d times - a check() in sort failed",
105	                         halt_seen);
106	                errors = errors + 1;
107	            end
108	
109	            // UART text
110	            if (uart_len != exp_len) begin
111	                $display("FAIL: UART length %0d != expected %0d", uart_len, exp_len);
112	                errors = errors + 1;
113	            end
114	            else begin
115	                for (i = 0; i < exp_len; i = i + 1)
116	                    if (uart_bytes[i] !== expected[8*(exp_len-1-i) +: 8]) begin
117	                        $display("FAIL: UART byte %0d = %h, expected %h",
118	                                 i, uart_bytes[i], expected[8*(exp_len-1-i) +: 8]);
119	                        errors = errors + 1;
120	                    end
121	                if (errors == 0)
122	                    $display("PASS: UART output (%0d bytes) matches expected sort text",
123	                             uart_len);
124	            end
125	
126	            // sorted arrays in RAM (byte addresses, little endian words)
127	            for (i = 0; i < 20; i = i + 1)
128	                if (core.mem.ram.data[9'h14 + 4*i] !== i[7:0]) begin
129	                    $display("FAIL: a[%0d] low byte = %h, expected %0d",
130	                             i, core.mem.ram.data[9'h14 + 4*i], i);
131	                    errors = errors + 1;
132	                end
133	            for (i = 0; i < 20; i = i + 1)
134	                if (core.mem.ram.data[9'h64 + 4*i] !== (19-i)) begin
135	                    $display("FAIL: b[%0d] low byte = %h, expected %0d",
136	                             i, core.mem.ram.data[9'h64 + 4*i], 19-i);
137	                    errors = errors + 1;
138	                end
139	
140	            if (errors == 0 && x_errors == 0)
141	                $display("PASS: sorted arrays correct in RAM, no X/Z in WB broadcasts");
142	            else
143	                $display("RESULT: %0d errors, %0d X/Z errors", errors, x_errors);
144	        end
145	    endtask
