1	`timescale 1ns / 1ps
2	// Testbench for lab5 scoreboard CPU (OoO, RV32IM).
3	// Instantiates RV32core directly, runs the pre-loaded rom.mem program
4	// (see lab5/ref/inst.S) and checks every WB-stage register write:
5	//   - no X/Z on RegWrite_ctrl / rd_ctrl / wt_data_WB when RegWrite_ctrl=1
6	//   - per-register write streams match the hand-executed expected values
7	//     (per-register order is architecturally guaranteed by the WAW stall,
8	//      even though the scoreboard retires instructions out of order)
9	//   - only registers x1,x2,x4,x5,x6,x7,x8,x9 (and harmless x0) are written
10	//   - the program keeps making progress (it loops via jalr to PC=0)
11	//
12	// Run vvp from lab5/core so ROM_D/RAM_B find rom.mem/ram.mem.
13	
14	module tb_rv32core;
15	
16	    reg clk = 0;
17	    reg rst = 1;
18	    always #5 clk = ~clk;   // 100MHz
19	
20	    wire [31:0] wb_addr, wb_data, clk_counter, debug_data;
21	
22	    RV32core core(
23	        .debug_en(1'b0),
24	        .debug_step(1'b0),
25	        .debug_addr(7'd0),
26	        .debug_data(debug_data),
27	        .wb_addr(wb_addr),
28	        .wb_data(wb_data),
29	        .clk_counter(clk_counter),
30	        .clk(clk),
31	        .rst(rst),
32	        .interrupter(1'b0)
33	    );
34	
35	    // hierarchical handles to the WB-stage signals inside RV32core
36	    wire        RegWrite_WB = core.RegWrite_ctrl;
37	    wire [4:0]  rd_WB       = core.rd_ctrl;
38	    wire [31:0] wt_data_WB  = core.wt_data_WB;
39	    wire [2:0]  write_sel   = core.DatatoReg_ctrl;
40	
41	    integer errors = 0;
42	    integer writes = 0;        // writes with rd != 0
43	    integer idx [1:31];        // per-register stream position
44	
45	    // expected per-register value streams (one program iteration each,
46	    // they repeat because jalr x1,0(x0) restarts the program at PC=0)
47	    // x1: 18, 17, 8, fffffffd, 00004000, 00000048, ffff0050, 00000068
48	    // x2: 00000008, 00000004
49	    // x4: 00000010   x5: 00000014   x6: ffff0000   x7: 0fff0000
50	    // x8: 01ffe000
51	    // x9: 00000140, 0fff0000
52	    reg [31:0] exp_val;
53	    reg [31:0] dummy;
54	
55	    task expect_write(input [4:0] rd, input [31:0] data);
56	        integer i;
57	        begin
58	            i = idx[rd];
59	            case (rd)
60	                1: case (i % 8)
61	                        0: exp_val = 32'h00000018;
62	                        1: exp_val = 32'h00000017;
63	                        2: exp_val = 32'h00000008;
64	                        3: exp_val = 32'hfffffffd;
65	                        4: exp_val = 32'h00004000;
66	                        5: exp_val = 32'h00000048;
67	                        6: exp_val = 32'hffff0050;
68	                        7: exp_val = 32'h00000068;
69	                   endcase
70	                2: exp_val = (i % 2 == 0) ? 32'h00000008 : 32'h00000004;
71	                4: exp_val = 32'h00000010;
72	                5: exp_val = 32'h00000014;
73	                6: exp_val = 32'hffff0000;
74	                7: exp_val = 32'h0fff0000;
75	                8: exp_val = 32'h01ffe000;
76	                9: exp_val = (i % 2 == 0) ? 32'h00000140 : 32'h0fff0000;
77	                default: exp_val = 32'hxxxxxxxx;
78	            endcase
79	            if (rd != 1 && rd != 2 && rd != 4 && rd != 5 &&
80	                rd != 6 && rd != 7 && rd != 8 && rd != 9) begin
81	                $display("ERROR @%0t: unexpected write to x%0d data=%h", $time, rd, data);
82	                errors = errors + 1;
83	            end
84	            else if (data !== exp_val) begin
85	                $display("ERROR @%0t: x%0d = %h, expected %h (stream idx %0d)",
86	                         $time, rd, data, exp_val, i);
87	                errors = errors + 1;
88	            end
89	            idx[rd] = i + 1;
90	            writes = writes + 1;
91	        end
92	    endtask
93	
94	    integer cyc = 0;
95	    integer k;
96	
97	    initial begin
98	        for (k = 0; k < 32; k = k + 1) idx[k] = 0;
99	        // hold reset for a few cycles
100	        repeat (5) @(posedge clk);
101	        #1 rst = 0;
102	
103	        // run long enough for several program iterations
104	        // (one iteration is ~120 cycles; div ~35 cycles, mul ~9 cycles)
105	        repeat (1200) @(posedge clk);
106	
107	        $display("--------------------------------------------------");
108	        $display("cycles run: %0d, WB writes (rd!=0): %0d, errors: %0d", cyc, writes, errors);
109	        if (writes < 51) begin
110	            $display("ERROR: too few WB writes, program not making progress");
111	            errors = errors + 1;
112	        end
113	        if (errors == 0) $display("TEST PASSED");
114	        else             $display("TEST FAILED (%0d errors)", errors);
115	        $finish;
116	    end
117	
118	    // sample WB stage once per cycle (just before the posedge that ends it)
119	    always @(negedge clk) begin
120	        if (!rst) begin
121	            cyc = cyc + 1;
122	            // X/Z checks on the WB control/data signals
123	            if (RegWrite_WB === 1'bx || RegWrite_WB === 1'bz) begin
124	                $display("ERROR @%0t: RegWrite_ctrl is %b", $time, RegWrite_WB);
125	                errors = errors + 1;
126	            end
127	            else if (RegWrite_WB) begin
128	                if (^rd_WB === 1'bx || ^wt_data_WB === 1'bx) begin
129	                    $display("ERROR @%0t: X/Z in WB write: rd=%b data=%b",
130	                             $time, rd_WB, wt_data_WB);
131	                    errors = errors + 1;
132	                end
133	                else begin
134	                    $display("cyc %4d: WB x%0d <- %h (write_sel=%0d)",
135	                             cyc, rd_WB, wt_data_WB, write_sel);
136	                    if (rd_WB != 0) expect_write(rd_WB, wt_data_WB);
137	                end
138	            end
139	        end
140	    end
141	
142	endmodule

1	`timescale 1ns / 1ps
2	// Functional verification TB for lab4 (5-stage pipeline + CMU cache).
3	// Monitors WB-stage register writes hierarchically inside RV32core and
4	// checks them against a hand-executed expected sequence, plus checks
5	// data_ram contents after the dirty store block is evicted (write-back).
6	//
7	// Notes on expected behavior of this design:
8	//  - During a cmu stall the MEM/WB register is frozen with RegWrite_WB=1,
9	//    so the same (PC,rd,data) write repeats until the stall ends. The TB
10	//    collapses consecutive identical writes.
11	//  - After the program ends it spins in "ori x16; jal -4", so the x16
12	//    write repeats forever; the TB accepts repeats of the final entry.
13	//  - A taken branch leaves a flushed nop bubble that reaches WB with
14	//    rd=x0; all rd=x0 writes are logged but not checked.
15	module tb_lab4;
16	    reg clk, rst;
17	    wire [31:0] debug_data, wb_pc, wb_inst;
18	    integer cycle = 0;
19	    integer errors = 0;
20	    integer exp_idx = 0;
21	
22	    RV32core core(
23	        .debug_en(1'b0),
24	        .debug_step(1'b0),
25	        .debug_addr(7'd0),
26	        .debug_data(debug_data),
27	        .clk(clk),
28	        .rst(rst),
29	        .wb_pc(wb_pc),
30	        .wb_inst(wb_inst),
31	        .mem_addr(),
32	        .mem_data(),
33	        .interrupter(1'b0)
34	    );
35	
36	    initial begin
37	        clk = 0;
38	        rst = 1;
39	        #6 rst = 0;
40	    end
41	    always #1 clk = ~clk;
42	
43	    // ---------------- expected WB sequence (hand-executed) ----------------
44	    // ROM program (ram.mem word 7 = F0F0F0F0, words >= 12 are 0 unless listed):
45	    //  0x00 00000013  nop
46	    //  0x04 01c00083  lb  x1, 28(x0)     ; byte0 F0 sext   -> x1=FFFFFFF0
47	    //  0x08 01c01103  lh  x2, 28(x0)     ; half F0F0 sext  -> x2=FFFFF0F0
48	    //  0x0c 01c02183  lw  x3, 28(x0)     ;                 -> x3=F0F0F0F0
49	    //  0x10 01c04203  lbu x4, 28(x0)     ;                 -> x4=000000F0
50	    //  0x14 01c05283  lhu x5, 28(x0)     ;                 -> x5=0000F0F0
51	    //  0x18 21002003  lw  x0, 0x210(x0)  ; rd=x0, not checked
52	    //  0x1c abcde0b7  lui x1, 0xabcde    ;                 -> x1=ABCDE000
53	    //  0x20 71c08093  addi x1, x1, 0x71c ;                 -> x1=ABCDE71C
54	    //  0x24 00100023  sb  x1, 0(x0)      ; mem[0].byte0 = 1C -> data[0]=0000801C
55	    //  0x28 00101223  sh  x1, 4(x0)      ; mem[1].half = E71C -> data[1]=0000E71C
56	    //  0x2c 00102423  sw  x1, 8(x0)      ;                    data[2]=ABCDE71C
57	    //  0x30 20002303  lw  x6, 0x200(x0)  ; ram word 128 = 0 -> x6=0 (miss, set 0)
58	    //  0x34 40002383  lw  x7, 0x400(x0)  ; ram word 256 = 0 -> x7=0 (evicts dirty blk0 -> write-back)
59	    //  0x38 41002403  lw  x8, 0x410(x0)  ; ram word 260 = 0 -> x8=0
60	    //  0x3c 0ed06813  ori x16, x0, 0xed  ;                 -> x16=000000ED
61	    //  0x40 ffdff06f  jal x0, -4         ; jumps to 0x3c: ori/jal loop forever
62	    reg [31:0] exp2_pc   [0:11];
63	    reg [4:0]  exp2_rd   [0:11];
64	    reg [31:0] exp2_data [0:11];
65	    localparam N_EXP2 = 11;
66	    initial begin
67	        exp2_pc[0]=32'h04; exp2_rd[0]=5'd1;  exp2_data[0]=32'hFFFFFFF0;
68	        exp2_pc[1]=32'h08; exp2_rd[1]=5'd2;  exp2_data[1]=32'hFFFFF0F0;
69	        exp2_pc[2]=32'h0C; exp2_rd[2]=5'd3;  exp2_data[2]=32'hF0F0F0F0;
70	        exp2_pc[3]=32'h10; exp2_rd[3]=5'd4;  exp2_data[3]=32'h000000F0;
71	        exp2_pc[4]=32'h14; exp2_rd[4]=5'd5;  exp2_data[4]=32'h0000F0F0;
72	        exp2_pc[5]=32'h1C; exp2_rd[5]=5'd1;  exp2_data[5]=32'hABCDE000;
73	        exp2_pc[6]=32'h20; exp2_rd[6]=5'd1;  exp2_data[6]=32'hABCDE71C;
74	        exp2_pc[7]=32'h30; exp2_rd[7]=5'd6;  exp2_data[7]=32'h00000000;
75	        exp2_pc[8]=32'h34; exp2_rd[8]=5'd7;  exp2_data[8]=32'h00000000;
76	        exp2_pc[9]=32'h38; exp2_rd[9]=5'd8;  exp2_data[9]=32'h00000000;
77	        exp2_pc[10]=32'h3C; exp2_rd[10]=5'd16; exp2_data[10]=32'h000000ED;
78	    end
79	
80	    // ------------- WB monitor: Regs commits writes on negedge clk -------------
81	    reg [31:0] last_pc, last_data;
82	    reg [4:0]  last_rd;
83	    reg        last_valid = 0;
84	
85	    always @(negedge clk) begin
86	        if (!rst) begin
87	            cycle = cycle + 1;
88	            if (core.RegWrite_WB === 1'b1) begin
89	                // X/Z checks
90	                if (^core.wt_data_WB === 1'bx) begin
91	                    $display("ERROR cyc=%0d PC=%h: X/Z in wt_data_WB=%h", cycle, core.PC_WB, core.wt_data_WB);
92	                    errors = errors + 1;
93	                end
94	                if (^core.rd_WB === 1'bx || ^core.PC_WB === 1'bx) begin
95	                    $display("ERROR cyc=%0d: X/Z in rd_WB/PC_WB", cycle);
96	                    errors = errors + 1;
97	                end
98	                // collapse consecutive identical writes (frozen WB during cmu stall)
99	                if (!(last_valid && core.PC_WB == last_pc && core.rd_WB == last_rd &&
100	                      core.wt_data_WB == last_data)) begin
101	                    $display("WB cyc=%0d PC=%h rd=x%0d data=%h inst=%h",
102	                             cycle, core.PC_WB, core.rd_WB, core.wt_data_WB, core.inst_WB);
103	                    if (core.rd_WB != 5'd0) begin
104	                        if (exp_idx < N_EXP2) begin
105	                            if (core.PC_WB !== exp2_pc[exp_idx] ||
106	                                core.rd_WB !== exp2_rd[exp_idx] ||
107	                                core.wt_data_WB !== exp2_data[exp_idx]) begin
108	                                $display("ERROR cyc=%0d: mismatch #%0d got PC=%h rd=x%0d data=%h, expected PC=%h rd=x%0d data=%h",
109	                                         cycle, exp_idx, core.PC_WB, core.rd_WB, core.wt_data_WB,
110	                                         exp2_pc[exp_idx], exp2_rd[exp_idx], exp2_data[exp_idx]);
111	                                errors = errors + 1;
112	                            end
113	                            exp_idx = exp_idx + 1;
114	                        end
115	                        else begin
116	                            // program finished: only the ori x16 loop write may repeat
117	                            if (!(core.PC_WB == 32'h3C && core.rd_WB == 5'd16 &&
118	                                  core.wt_data_WB == 32'h000000ED)) begin
119	                                $display("ERROR cyc=%0d: unexpected WB after program end PC=%h rd=x%0d data=%h",
120	                                         cycle, core.PC_WB, core.rd_WB, core.wt_data_WB);
121	                                errors = errors + 1;
122	                            end
123	                        end
124	                    end
125	                end
126	                last_pc = core.PC_WB; last_rd = core.rd_WB; last_data = core.wt_data_WB;
127	                last_valid = 1;
128	            end
129	        end
130	    end
131	
132	    // ------------- run long enough for cache misses / write-back -------------
133	    initial begin
134	        #4000;
135	        $display("----------------------------------------------------------");
136	        if (exp_idx != N_EXP2) begin
137	            $display("ERROR: only %0d of %0d expected WB writes observed", exp_idx, N_EXP2);
138	            errors = errors + 1;
139	        end
140	        // store results must have reached data_ram via cache write-back
141	        $display("data_ram[0..3] = %h %h %h %h",
142	                 core.RAM.data[0], core.RAM.data[1], core.RAM.data[2], core.RAM.data[3]);
143	        if (core.RAM.data[0] !== 32'h0000801C) begin
144	            $display("ERROR: data_ram[0]=%h expected 0000801C (sb write-back)", core.RAM.data[0]);
145	            errors = errors + 1;
146	        end
147	        if (core.RAM.data[1] !== 32'h0000E71C) begin
148	            $display("ERROR: data_ram[1]=%h expected 0000E71C (sh write-back)", core.RAM.data[1]);
149	            errors = errors + 1;
150	        end
151	        if (core.RAM.data[2] !== 32'hABCDE71C) begin
152	            $display("ERROR: data_ram[2]=%h expected ABCDE71C (sw write-back)", core.RAM.data[2]);
153	            errors = errors + 1;
154	        end
155	        if (core.RAM.data[3] !== 32'h00000014) begin
156	            $display("ERROR: data_ram[3]=%h expected 00000014 (untouched)", core.RAM.data[3]);
157	            errors = errors + 1;
158	        end
159	        // confirm the CPU reached the final ori/jal spin loop
160	        if (core.PC_IF > 32'h00000044) begin
161	            $display("WARNING: PC_IF=%h at end, expected to be spinning in 0x3c-0x44", core.PC_IF);
162	        end
163	        if (errors == 0)
164	            $display("TB RESULT: PASS (all %0d expected WB writes matched, store write-back verified, no X/Z)", N_EXP2);
165	        else
166	            $display("TB RESULT: FAIL (%0d errors)", errors);
167	        $finish;
168	    end
169	
170	endmodule

